-- Seed section hover tooltips (run once; Worker updates these after content changes).
INSERT OR REPLACE INTO site_config (key, value) VALUES (
  'section_hints',
  '{"Thinking":"Short notes, photos, and passing thoughts—updated often, with none of the polish of a full essay. You''ll find book quotes, travel snapshots, NYC gripes, sports reactions, politics, art, and whatever''s on my mind right now. It''s the informal layer of the site: loose, opinionated, sometimes funny, sometimes ranty, always in the moment.","Writing":"Longer pieces when I have something to say—a mix of personal essays, small experiments, and the occasional haiku. Topics wander from style and walking to film, routine, building this site, and what it means to pay attention. Less of a diary, more room to think out loud.","Reading":"A log of books I''m reading, linked to Bookshop.org and grouped by month. Mostly literary fiction and translated work—the kind of books you''d find on a serious reader''s nightstand, not a bestseller list. It''s a snapshot of what''s open on my desk, not reviews or ratings.","Sharing":"Sharing is a linklog—a running list of links that caught my eye, with no commentary, just the title and the URL, newest first. If you browse it, you''ll find a mix that reflects how I actually use the internet: art and design, literature and poetry, architecture, NYC politics, sports, history, film, and the occasional rabbit hole (indie web, style, food, a perfect photo). It''s not a news feed or a hot-take column—more a personal signal of what I''m reading, noticing, and think is worth a click, high and low, serious and playful, all in one stream."}'
);
